# v110: „Árak és bérek 301-ben: Diocletianus árrendelete” kártya (hu/en).
# Adat: az árrendelet tételei A. Kropff angol fordítása (2016, 2.1 változat) szerint, Lauffer (1971) számozásával; a kigyűjtött sorokat egyenként átolvastam.
KMOD,SEXT,LB=17.51,0.547,0.32745   # Lauffer 1971, 54–55 (Kropff nyomán): kastrensis modius (l), sextarius (l), libra (kg)
# napibérek ellátással (dénár/nap): (szám, hu, en, bér)
WAGE=[('7.1a','mezőgazdasági napszámos','farm labourer',25),('7.31','vízhordó','water carrier',25),('7.32','csatornatisztító','sewer cleaner',25),('7.19','öszvérhajcsár','mule driver',25),('7.18','juhász','shepherd',25),
 ('7.2','kőfaragó','stonemason',50),('7.3a','ács','carpenter',50),('7.12','pék','baker',50),('7.11','kocsikovács','blacksmith for wagons',50),('7.14','hajóács (folyami hajó)','shipwright (river vessels)',50),
 ('7.13','hajóács (tengeri hajó)','shipwright (seagoing vessels)',60),('7.5','márványpadló-rakó','worker in marble pavements',60),('7.6','falmozaik-készítő','worker in wall mosaics',60),('7.8','falfestő','wall painter',75),('7.9','képfestő','figure painter',150)]
# egyéb díjak: (szám, hu, en, díj, egység hu, egység en)
FEE=[('7.22','borbély','barber',2,'vendégenként','per client'),('7.75','ruhaőr a közfürdőben','clothes guard in a public bath',2,'fürdőzőnként','per bather'),('7.39','írnok, a legszebb írás','scribe, best writing',25,'100 soronként','per 100 lines'),('7.41','jegyző, beadvány vagy jogi irat','notary, petitions or legal documents',10,'100 soronként','per 100 lines'),
 ('7.66','elemi iskolai tanító','elementary teacher',50,'havonta, tanulónként','monthly, per pupil'),('7.67','számtantanító','teacher of arithmetic',75,'havonta, tanulónként','monthly, per pupil'),('7.70','görög vagy latin irodalom és geometria tanára','teacher of Greek or Latin literature and geometry',200,'havonta, tanulónként','monthly, per pupil'),('7.71','rétor','teacher of rhetoric',250,'havonta, tanulónként','monthly, per pupil'),('7.73','ügyvéd, egy ügy képviselete','advocate, pleading a case',1000,'ügyenként','per case')]
# élelmiszer: (szám, hu, en, ár, egység: 'k' k.modius, 's' sextarius, 'l' libra, 'd' darab, darabszám)
FOOD=[('1.1a','búza','wheat',100,'k',1),('1.2','árpa','barley',60,'k',1),('1.11','lencse','lentils',100,'k',1),('3.8','só','salt',100,'k',1),
 ('2.10','közönséges bor','ordinary wine',8,'s',1),('2.7','falernusi bor','Falernian wine',30,'s',1),('2.12','árpasör','barley beer',2,'s',1),
 ('3.3','közönséges olívaolaj','ordinary olive oil',12,'s',1),('3.1a','első sajtolású olívaolaj','virgin olive oil, first quality',40,'s',1),('3.7','halszósz, másodosztályú','fish sauce, second quality',12,'s',1),('3.10','méz, legjobb minőség','honey, best quality',40,'s',1),
 ('4.1a','sertéshús','pork',12,'l',1),('4.2','marhahús','beef',8,'l',1),('4.3','kecske- vagy birkahús','goat’s meat or mutton',8,'l',1),('5.2','tengeri hal, másodosztályú','sea fish, second quality',16,'l',1),('5.4','folyami hal, másodosztályú','river fish, second quality',8,'l',1),('5.5','sózott hal','salted fish',6,'l',1),('6.96','friss sajt','fresh cheese',8,'l',1),('4.50','vaj','butter',16,'l',1),
 ('6.43','tojás','eggs',4,'d',4),('4.23','csirke','chickens',60,'d',2),('6.10','káposzta, másodosztályú','cabbage, second quality',4,'d',10)]
SEA=[('37.1a','Alexandria – Róma','Alexandria – Rome',16),('37.22','Ephesus – Róma','Ephesus – Rome',16),('37.11','Syria – Róma','Syria – Rome',18),('37.38','Nicomedia – Róma','Nicomedia – Rome',18),('37.33','Róma – Thessalonica','Rome – Thessalonica',18),('37.34','Róma – Achaia','Rome – Achaea',14),('37.35','Róma – Hispania','Rome – Hispania',10),('37.32','Róma – Sicilia','Rome – Sicily',6),('37.36','Róma – Gallia','Rome – Gaul',4)]
def build(l):
    H=l=='hu';T=lambda h,e:h if H else e
    fmt=(lambda n:f'{n:,}'.replace(',',' ')) if H else (lambda n:f'{n:,}')
    def d(x,k=1):
        s=f'{x:.{k}f}';return s.replace('.',',') if H else s
    o=[]
    o.append('    <section class="card" id="pricecard">')
    o.append('      <h2>'+T('Árak és bérek 301-ben: Diocletianus árrendelete','Prices and wages in 301: Diocletian’s Price Edict')+'</h2>')
    o.append('      <p class="hint">'+T('Kr. u. 301 végén Diocletianus és társcsászárai rendeletben szabták meg több mint 1200 áru, munka és szolgáltatás legmagasabb árát. Ez az egyetlen ókori forrás, amelyből egyszerre látszik, mennyit kereshetett egy napszámos, és mit kapott érte. Az árak <i>denarius communis</i>ban állnak: ez ekkor már számolási egység volt, nem forgalomban lévő érme.','At the end of AD 301 Diocletian and his co-emperors fixed by edict the maximum price of more than 1,200 goods, kinds of work and services. It is the only ancient source that shows at once how much a day labourer could earn and what he got for it. Prices are given in <i>denarii communes</i>: by then a unit of account, not a coin in circulation.')+'</p>')
    o.append('      <p class="hint">'+T('<b>Mire kell vigyázni.</b> A számok megengedett legmagasabb árak, nem piaci árak, és az egész birodalomra szólnak, nem Rómára: a városban az élelmiszer egy részét az állam osztotta (lásd „Róma élelmezése”). A rendelet kőbe vésett töredékei egy kivételével a birodalom keleti feléből kerültek elő, és nem tudjuk, nyugaton mennyire tartották be; Lactantius szerint az áruk eltűntek a piacról, és a rendeletet vissza kellett vonni.','<b>What to watch for.</b> The figures are maximum permitted prices, not market prices, and they apply to the whole empire, not to Rome: in the city part of the food was distributed by the state (see “Feeding Rome”). All but one of the inscribed fragments of the edict come from the eastern half of the empire, and we do not know how far it was observed in the west; according to Lactantius goods vanished from the market and the edict had to be withdrawn.')+'</p>')
    o.append('      <h3 class="aqh">'+T('Napibérek','Daily wages')+'</h3>')
    mx=max(w for *_,w in WAGE)
    o.append('      <div class="prbars">'+''.join('<div class="pbr"><span class="pbl">%s</span><span class="pbb" style="width:%.1f%%"></span><span class="pbn">%d</span></div>'%(T(hu,en),100*w/mx*0.5,w) for n,hu,en,w in WAGE)+'</div>')
    SRC=T('Diocletianus árrendelete (<i>Edictum de pretiis rerum venalium</i>, Kr. u. 301), a tételek S. Lauffer (1971) számozása és A. Kropff angol fordítása (2016) szerint.','Diocletian’s Price Edict (<i>Edictum de pretiis rerum venalium</i>, AD 301), items after the numbering of S. Lauffer (1971) and the English translation of A. Kropff (2016).')
    o.append('      <p class="hint aqleg">'+T('Dénár naponta, ellátással együtt (a munkaadó az élelmet is adta). A rendelet 7. fejezete.','Denarii per day, with maintenance (the employer also provided food). Chapter 7 of the edict.')+'</p>')
    o.append('      <p class="hint srcl"><b>'+T('Forrás:','Source:')+'</b> '+SRC+'</p>')
    o.append('      <div class="regwrap"><table class="regtab aniotab prtab">')
    o.append('        <thead><tr><th>'+T('Más díjak','Other fees')+'</th><th>'+T('Dénár','Denarii')+'</th><th>'+T('Egység','Unit')+'</th></tr></thead>')
    o.append('        <tbody>')
    for n,hu,en,w,uh,ue in FEE: o.append('          <tr><td>'+T(hu,en)+'</td><td>'+fmt(w)+'</td><td>'+T(uh,ue)+'</td></tr>')
    o.append('        </tbody>')
    o.append('      </table></div>')
    o.append('      <p class="hint srcl"><b>'+T('Forrás:','Source:')+'</b> '+SRC+'</p>')
    o.append('      <p class="hint">'+T('A szakmunkás a napszámos kétszeresét, a képfestő a hatszorosát kaphatta. Egy rétor egyetlen tanítványa után havonta annyit kérhetett, amennyit a napszámos tíz nap alatt keresett.','A skilled worker could get twice a labourer’s wage, a figure painter six times. For a single pupil a teacher of rhetoric could charge per month as much as a labourer earned in ten days.')+'</p>')
    o.append('      <h3 class="aqh">'+T('Élelmiszerárak, és mit ért egy napszám','Food prices, and what a day’s wage bought')+'</h3>')
    o.append('      <div class="regwrap"><table class="regtab prtab2">')
    o.append('        <thead><tr><th>'+T('Áru','Item')+'</th><th>'+T('A rendeletben','In the edict')+'</th><th>'+T('Mai egységre','In modern units')+'</th><th>'+T('25 dénárért (napszámos)','For 25 denarii (labourer)')+'</th><th>'+T('50 dénárért (szakmunkás)','For 50 denarii (skilled worker)')+'</th></tr></thead>')
    o.append('        <tbody>')
    for n,hu,en,p,u,q in FOOD:
        if u=='k': ed=T('%d dénár / tábori modius'%p,'%d den. / camp modius'%p);mod=T('%s dénár / liter'%d(p/KMOD),'%s den. / litre'%d(p/KMOD));b=lambda w:T('%s liter'%d(w/p*KMOD),'%s litres'%d(w/p*KMOD))
        elif u=='s': ed=T('%d dénár / sextarius'%p,'%d den. / sextarius'%p);mod=T('%s dénár / liter'%d(p/SEXT),'%s den. / litre'%d(p/SEXT));b=lambda w:T('%s liter'%d(w/p*SEXT,2),'%s litres'%d(w/p*SEXT,2))
        elif u=='l': ed=T('%d dénár / font'%p,'%d den. / pound'%p);mod=T('%s dénár / kg'%d(p/LB),'%s den. / kg'%d(p/LB));b=lambda w:T('%s kg'%d(w/p*LB,2),'%s kg'%d(w/p*LB,2))
        else: ed=T('%d dénár / %d darab'%(p,q),'%d den. / %d pieces'%(p,q));mod=T('%s dénár / darab'%d(p/q),'%s den. each'%d(p/q));b=lambda w:T('%d darab'%round(w/p*q),'%d pieces'%round(w/p*q))
        o.append('          <tr><td>'+T(hu,en)+'</td><td>'+ed+'</td><td>'+mod+'</td><td>'+b(25)+'</td><td>'+b(50)+'</td></tr>')
    o.append('        </tbody>')
    o.append('      </table></div>')
    o.append('      <p class="hint srcl"><b>'+T('Forrás:','Source:')+'</b> '+SRC+' '+T('Az átszámítás saját: 1 tábori modius = 17,51 liter, 1 sextarius = 0,547 liter, 1 római font = 327,45 gramm (Lauffer 1971).','The conversion is our own: 1 camp modius = 17.51 litres, 1 sextarius = 0.547 litres, 1 Roman pound = 327.45 grams (Lauffer 1971).')+'</p>')
    o.append('      <p class="hint">'+T('A napszámos egynapi bére %s liter búzára vagy %s kiló sertéshúsra volt elég, miközben az ételét a munkaadótól kapta; a bér a családjára és a lakására maradt. A tábori modius (<i>modius castrensis</i>) űrtartalma vitatott: itt Lauffer értéke szerepel, más kutatók ennél kisebbnek veszik, akkor a gabonafélék literára ennyivel magasabb.'%(d(25/100*KMOD),d(25/12*LB,2)),'A labourer’s daily wage was enough for %s litres of wheat or %s kilos of pork, while he got his food from the employer; the wage was left for his family and his lodging. The capacity of the camp modius (<i>modius castrensis</i>) is disputed: Lauffer’s value is used here; other scholars take it to be smaller, in which case the per-litre price of grain is correspondingly higher.'%(d(25/100*KMOD),d(25/12*LB,2)))+'</p>')
    o.append('      <h3 class="aqh">'+T('Hajófuvar Rómába és Rómából','Sea freight to and from Rome')+'</h3>')
    mxs=max(p for *_,p in SEA)
    o.append('      <div class="prbars sea">'+''.join('<div class="pbr"><span class="pbl">%s</span><span class="pbb" style="width:%.1f%%"></span><span class="pbn">%d</span></div>'%(T(hu,en),100*p/mxs*0.5,p) for n,hu,en,p in SEA)+'</div>')
    o.append('      <p class="hint aqleg">'+T('Dénár egy tábori modius (17,51 liter) áru szállításáért. A rendelet 37. fejezete; az Africa – Róma útvonal díja a töredékeken nem maradt fenn.','Denarii for carrying one camp modius (17.51 litres) of goods. Chapter 37 of the edict; the rate for the Africa – Rome route does not survive on the fragments.')+'</p>')
    o.append('      <p class="hint srcl"><b>'+T('Forrás:','Source:')+'</b> '+SRC+'</p>')
    o.append('      <p class="hint">'+T('Egy modius búza legmagasabb ára 100 dénár volt, az Alexandriából Rómába szállításé 16: a tengeri út tehát a búza árának legfeljebb hatodát tette ki. Szárazföldön egy 1200 fontos (kb. 393 kg) szekérrakomány fuvardíja mérföldenként 20 dénár (17.3. tétel); ezért érte meg a gabonát Egyiptomból hajón hozni, és nem Itália belsejéből szekéren.','The maximum price of a modius of wheat was 100 denarii, that of shipping it from Alexandria to Rome 16: so the sea voyage made up at most a sixth of the price of wheat. By land the freight charge for a wagonload of 1,200 pounds (about 393 kg) was 20 denarii per mile (item 17.3); this is why it paid to bring grain by ship from Egypt rather than by wagon from inland Italy.')+'</p>')
    o.append('      <h3 class="aqh">'+T('A skála két vége','The two ends of the scale')+'</h3>')
    o.append('      <div class="regwrap"><table class="regtab aniotab prtab">')
    o.append('        <thead><tr><th>'+T('Tétel','Item')+'</th><th>'+T('Dénár','Denarii')+'</th><th>'+T('Napszámban (25 dénár)','In days of labour (25 denarii)')+'</th></tr></thead>')
    o.append('        <tbody>')
    BIG=[('31.1a','rabszolga, 16–40 éves férfi','slave, man aged 16–40',30000),('31.2','rabszolga, 16–40 éves nő','slave, woman aged 16–40',25000),('30.1a','egy font (327 g) finomított arany','a pound (327 g) of refined gold',72000),('30.9','egy font első osztályú ezüst','a pound of first-quality silver',6000),('9.7','patríciuscipő','shoes for patricians',150),('9.6','katonacsizma, szegek nélkül','soldier’s boots, without hobnails',100),('9.12a','paraszti gall szandál, dupla talpú','Gallic sandals for farm workers, double-soled',80),('4.23','egy pár csirke','a pair of chickens',60)]
    for n,hu,en,p in BIG: o.append('          <tr><td>'+T(hu,en)+'</td><td>'+fmt(p)+'</td><td>'+(fmt(round(p/25)) if p/25>=10 else d(p/25))+'</td></tr>')
    o.append('        </tbody>')
    o.append('      </table></div>')
    o.append('      <p class="hint srcl"><b>'+T('Forrás:','Source:')+'</b> '+SRC+' '+T('A napszámra átszámítás saját.','The conversion into days of labour is our own.')+'</p>')
    o.append('      <p class="hint">'+T('Egy felnőtt férfi rabszolga ára 1200 napszámnak felelt meg, vagyis egy napszámos több mint három évi teljes keresetének. Az arany és az ezüst aránya 12 : 1. A rendeletet megelőző pénzromlásról lásd „Éremkincsek: mikor rejtettek el pénzt”.','The price of an adult male slave corresponded to 1,200 days of labour, that is, more than three years of a labourer’s entire earnings. The ratio of gold to silver is 12 : 1. On the debasement that preceded the edict see “Coin hoards: when money was hidden”.')+'</p>')
    o.append('    </section>')
    return '\n'.join(o)+'\n'
SUB=('napibérek, élelmiszerárak és hajófuvar Diocletianus árrendeletéből; mit ért egy napszám','daily wages, food prices and sea freight from Diocletian’s Price Edict; what a day’s wage bought')
SRCLI=lambda l:('      <li><b>Árak és bérek 301-ben.</b> <i>Edictum Diocletiani de pretiis rerum venalium</i> (Kr. u. 301). Kiadás és számozás: S. Lauffer: <i>Diokletians Preisedikt</i>, Berlin 1971; a tételek olvasata A. Kropff: <i>An English translation of the Edict on Maximum Prices, also known as the Price Edict of Diocletian</i>, 2.1 változat, 2016 szerint (E. R. Graser 1940, Lauffer 1971, Crawford–Reynolds 1979 és Salway 2010 nyomán). A mértékegységek átszámítása Lauffer 1971, 54–55. A rendelet hatásáról: Lactantius, <i>De mortibus persecutorum</i> 7.6–7. A válogatás, a magyar megnevezések és a számítások sajátok.</li>' if l=='hu' else '      <li><b>Prices and wages in 301.</b> <i>Edictum Diocletiani de pretiis rerum venalium</i> (AD 301). Edition and numbering: S. Lauffer: <i>Diokletians Preisedikt</i>, Berlin 1971; items read after A. Kropff: <i>An English translation of the Edict on Maximum Prices, also known as the Price Edict of Diocletian</i>, version 2.1, 2016 (after E. R. Graser 1940, Lauffer 1971, Crawford–Reynolds 1979 and Salway 2010). Conversion of measures: Lauffer 1971, 54–55. On the effect of the edict: Lactantius, <i>De mortibus persecutorum</i> 7.6–7. The selection, the item names and the calculations are our own.</li>')
if __name__=='__main__':
    print(len(build('hu').split('\n')),len(build('en').split('\n')),round(25/100*KMOD,2),round(25/12*LB,3),30000/25)
